import { describe, it, expect } from 'vitest';
import * as git from 'isomorphic-git';
import {
  recordEvent,
  replayEvents,
  getDatabase,
  insertNode,
  createTestContext,
  type HiveContext,
  type Node,
} from '@hive/core';

const branch = 'hive-test';
async function bootstrap(): Promise<{ ctx: HiveContext; dir: string }> {
  const dir = '/test-repo';
  const ctx = await createTestContext(dir);
  ctx.fs.mkdirSync(dir, { recursive: true });
  ctx.fs.mkdirSync(`${dir}/.hive`, { recursive: true });
  await git.init({ fs: ctx.fs as any, dir, defaultBranch: 'main' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.name', value: 'Test User' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.email', value: 'test@example.com' });
  ctx.fs.writeFileSync(`${dir}/README.md`, '# Test');
  await git.add({ fs: ctx.fs as any, dir, filepath: 'README.md' });
  await git.commit({ fs: ctx.fs as any, dir, message: 'Initial commit',
    author: { name: 'Test User', email: 'test@example.com' } });
  await git.branch({ fs: ctx.fs as any, dir, ref: branch });
  return { ctx, dir };
}
async function addNode(ctx: HiveContext, title: string): Promise<string> {
  const id = await recordEvent(ctx, { type: 'add', nodeType: 'decision', content: title, confidence: 90 }, branch);
  const db = getDatabase(ctx);
  const now = new Date().toISOString();
  const node: Node = { change_id: id, branch, node_type: 'decision', title, status: 'pending', created_at: now, updated_at: now };
  insertNode(db, node);
  return id;
}

describe('link event referential integrity', () => {
  it('does not materialise an edge whose endpoints reference no existing node', async () => {
    const { ctx } = await bootstrap();

    // A link event whose fromId/toId are node ids that were never inserted as nodes.
    const fromId = crypto.randomUUID();
    const toId = crypto.randomUUID();
    await recordEvent(ctx, { type: 'link', fromId, toId, edgeType: 'leads_to' }, branch);

    // Force a full rebuild so the link commit is replayed through replayEvent.
    await replayEvents(ctx, branch, true);

    const db = getDatabase(ctx);
    const edges = db.prepare('SELECT from_change_id, to_change_id FROM edges').all() as {
      from_change_id: string;
      to_change_id: string;
    }[];

    // Referential integrity should hold: no edge may point at a non-existent node.
    const orphanEdges = edges.filter((e) => {
      const from = db.prepare('SELECT 1 FROM nodes WHERE change_id = ?').get(e.from_change_id);
      const to = db.prepare('SELECT 1 FROM nodes WHERE change_id = ?').get(e.to_change_id);
      return !from || !to;
    });

    expect(orphanEdges).toHaveLength(0);
  });
});
